08:30:18.784Z","message.seq":2193,"resources":[],"sender":{"id":"ouvjhgphs7fnzd"}},{"message.content":"后面也可以用这个项目里的真实数据测试AI助手的功能。","message.content_type":"text","message.conversation_id":"sg_3981594831","message.send_time":"2026-11-02T08:32:31.62Z","message.seq":2194,"resources":[],"sender":{"id":"ouvjhgphs7fnzd"}},{"message.content":"@守白 你用 API 创建的吧？你试试用 AI 助手的写入功能创建项目和任务看看？好用不","message.content_type":"at_text","message.conversation_id":"sg_3981594831","message.send_time":"2026-11-02T08:40:59.474Z","message.seq":2201,"resources":[],"sender":{"id":"ouvkmtuntg5xpk"}},{"message.content":"@SuChen 对，因为现在还没openAPI所以先用我自己的token和现在空间任务的http接口，这周自定义字段上线完我是想试一下基于这个项目的数据自动生成一些报告给士衡。之前用的JIRA的AI助手","message.content_type":"at_text","message.conversation_id":"sg_3981594831","message.send_time":"2026-11-02T08:48:09.596Z","message.seq":2203,"resources":[],"sender":{"id":"ouvjhgphs7fnzd"}},{"message.content":"@守白 晚上禁用了自动化","message.content_type":"at_text","message.conversation_id":"sg_3981594831","message.send_time":"2026-11-03T01:43:56.576Z","message.seq":2209,"resources":[],"sender":{"id":"ouv4qluqoynfcv"}},{"message.content":"￼
